airflow_otel-scheduler-heartbeat-low.esql:
FROM metrics-airflow.otel-default*
| WHERE data_stream.dataset == "airflow.otel"
// Count scheduler heartbeats in the rule's time window
| STATS hb_count = COUNT(airflow.scheduler_heartbeat), total_docs = COUNT(*)
// Alert when we have Airflow activity but fewer than 5 heartbeats
// Adjust threshold (5) for your scheduler heartbeat cadence
| WHERE total_docs > 10 AND hb_count < 5

apache_otel-availability-server-restart.esql:
// Alert triggers when Apache server uptime resets, indicating a restart.
// A restart is detected when the current uptime is significantly lower than the previous maximum,
// which suggests the server was restarted.
// You can adjust the threshold value by modifying the uptime_seconds in the WHERE clause.
FROM metrics-apachereceiver.otel-*
| STATS max_uptime = MAX(metrics.apache.uptime), min_uptime = MIN(metrics.apache.uptime) BY resource.attributes.host.name
| WHERE max_uptime IS NOT NULL AND min_uptime IS NOT NULL
| EVAL uptime_delta = max_uptime - min_uptime
| WHERE min_uptime < 300 AND uptime_delta > 300
| KEEP resource.attributes.host.name, min_uptime, max_uptime, uptime_delta
| SORT min_uptime ASC

apache_otel-capacity-low-idle-workers.esql:
// Alert triggers when the number of idle workers falls below the threshold.
// Low idle workers indicate the server is approaching capacity and may not handle new requests efficiently.
// The alert is grouped by host name.
// You can adjust the threshold value by modifying the idle_workers in the WHERE clause (default: < 5).
FROM metrics-apachereceiver.otel-*
| WHERE attributes.state == "idle"
| STATS idle_workers = AVG(metrics.apache.workers) BY resource.attributes.host.name
| WHERE idle_workers IS NOT NULL AND idle_workers < 5
| EVAL idle_workers = ROUND(idle_workers, 2)
| KEEP resource.attributes.host.name, idle_workers
| SORT idle_workers ASC

apache_otel-performance-high-server-load.esql:
// Alert triggers when the Apache server load (1-minute average) exceeds the threshold.
// High server load indicates the server is under heavy demand and may experience performance degradation.
// The alert is grouped by host name.
// You can adjust the threshold value by modifying the server_load in the WHERE clause (default: > 0.8 = 80%).
FROM metrics-apachereceiver.otel-*
| STATS server_load = AVG(metrics.apache.load.1) BY resource.attributes.host.name
| WHERE server_load IS NOT NULL AND server_load > 0.8
| EVAL server_load = ROUND(server_load, 3)
| KEEP resource.attributes.host.name, server_load
| SORT server_load DESC

apache_tomcat_otel-high-jvm-process-cpu.esql:
FROM metrics-tomcat.otel-*
| WHERE java_lang_OperatingSystem_ProcessCpuLoad IS NOT NULL
| STATS avg_cpu = AVG(java_lang_OperatingSystem_ProcessCpuLoad)
  BY host.name
| EVAL cpu_pct = ROUND(avg_cpu * 100.0, 2)
// JVM process CPU threshold — sustained high CPU often correlates with
// GC pressure, thread contention, or compute-heavy request processing
// Adjust based on expected workload and available CPU cores
| WHERE cpu_pct > 90.0
| SORT cpu_pct DESC

aws-bedrock-agentcore-agent-runtime-high.esql:
// Alert triggers when high latency is detected during AWS Bedrock AgentCore runtime invocations.
//
// Latency measures the average time elapsed between receiving the request and
// sending the final response token, measured in milliseconds.
//
// The alert is grouped by cloud account, region, and agent endpoint name (aws.dimensions.Name)
// to pinpoint the specific agent endpoint experiencing high latency.
//
// To adjust sensitivity, change the threshold in the WHERE clause (default: 10000ms = 10 seconds).

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation == "InvokeAgentRuntime"
| STATS avg_latency_ms = avg(aws.bedrock_agentcore.metrics.Latency.avg) BY cloud.account.id, cloud.region, aws.dimensions.Name
| WHERE avg_latency_ms > 10000

aws-bedrock-agentcore-agent-runtime-syst.esql:
// Alert triggers when system errors occur during AWS Bedrock AgentCore runtime invocations.
//
// System errors correspond to InvocationError.Internal - Internal server error (500).
// These are server-side errors indicating infrastructure or service issues.
//
// The alert is grouped by cloud account, region, and agent endpoint name (aws.dimensions.Name)
// to pinpoint the specific agent endpoint experiencing issues.
//
// To reduce alert noise, increase the threshold (e.g., `total_system_errors > 5`) to only
// alert on sustained error patterns rather than transient service disruptions.

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation == "InvokeAgentRuntime"
| STATS total_system_errors = sum(aws.bedrock_agentcore.metrics.SystemErrors.sum) BY cloud.account.id, cloud.region, aws.dimensions.Name
| WHERE total_system_errors > 0

aws-bedrock-agentcore-agent-runtime-user.esql:
// Alert triggers when user errors occur during AWS Bedrock AgentCore runtime invocations.
//
// User errors correspond to client-side errors (4xx) including:
// - InvocationError.Validation - Client provided invalid input (400)
// - InvocationError.ResourceNotFound - Requested resource doesn't exist (404)
// - InvocationError.AccessDenied - Client lacks permissions (403)
// - InvocationError.Conflict - Resource conflict (409)
//
// The alert is grouped by cloud account, region, and agent endpoint name (aws.dimensions.Name)
// to pinpoint the specific agent endpoint experiencing issues.
//
// To reduce alert noise, increase the threshold (e.g., `total_user_errors > 10`) to only
// alert on sustained error patterns rather than isolated incidents.

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation == "InvokeAgentRuntime"
| STATS total_user_errors = sum(aws.bedrock_agentcore.metrics.UserErrors.sum) BY cloud.account.id, cloud.region, aws.dimensions.Name
| WHERE total_user_errors > 0

aws-bedrock-agentcore-browser-errors.esql:
// Alert triggers when errors occur during AWS Bedrock AgentCore Browser operations.
//
// Browser tool enables agents to interact with web pages programmatically,
// automating web-based tasks. Operations include:
// - StartBrowserSession: Initiates a new browser automation session
// - StopBrowserSession: Terminates a browser session
// - ConnectBrowserAutomationStream: Establishes automation stream connection
// - ConnectBrowserLiveViewStream: Establishes live view stream
// - GetBrowserSession/ListBrowserSessions: Session management operations
//
// This alert monitors both user errors (4xx) and system errors (5xx).
//
// The alert is grouped by cloud account, region, and resource to pinpoint
// specific browser sessions experiencing issues.
//
// To reduce alert noise, increase the threshold (e.g., `total_errors > 5`).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/browser-metrics.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("StartBrowserSession", "StopBrowserSession", "ConnectBrowserAutomationStream", "ConnectBrowserLiveViewStream", "GetBrowserSession", "ListBrowserSessions", "UpdateBrowserStream")
| STATS total_user_errors = sum(aws.bedrock_agentcore.metrics.UserErrors.sum), total_system_errors = sum(aws.bedrock_agentcore.metrics.SystemErrors.sum) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| EVAL total_errors = COALESCE(total_user_errors, TO_LONG(0)) + COALESCE(total_system_errors, TO_LONG(0))
| WHERE total_errors > 0

aws-bedrock-agentcore-browser-session-th.esql:
// Alert triggers when throttling occurs during AWS Bedrock AgentCore Browser operations.
//
// Browser session throttling indicates that requests are being rate-limited,
// which can impact agent ability to perform web automation tasks.
//
// Common causes of browser throttling:
// - High volume of browser session requests
// - Concurrent session limits exceeded
// - Resource quota constraints
//
// The alert is grouped by cloud account, region, and resource to identify
// which browser resources are being throttled.
//
// To reduce alert noise, increase the threshold (e.g., `total_throttles > 10`).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/browser-metrics.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("StartBrowserSession", "StopBrowserSession", "ConnectBrowserAutomationStream", "ConnectBrowserLiveViewStream")
| STATS total_throttles = sum(aws.bedrock_agentcore.metrics.Throttles.sum) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| WHERE total_throttles > 0

aws-bedrock-agentcore-code-interpreter-e.esql:
// Alert triggers when errors occur during AWS Bedrock AgentCore Code Interpreter operations.
//
// Code Interpreter enables agents to execute code within secure, isolated sessions.
// This alert monitors both user errors (client-side, 4xx) and system errors (server-side, 5xx)
// across all Code Interpreter operations including:
// - StartCodeInterpreterSession: Initiates a new code execution session
// - InvokeCodeInterpreter: Executes code within an active session
// - StopCodeInterpreterSession: Terminates an active session
// - CodeInterpreterSession: Session lifecycle metrics
//
// The alert is grouped by cloud account, region, and resource to pinpoint the
// specific Code Interpreter experiencing issues.
//
// To reduce alert noise, increase the threshold (e.g., `total_errors > 5`) to only
// alert on sustained error patterns rather than isolated incidents.
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/code-interpreter-observability.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("StartCodeInterpreterSession", "InvokeCodeInterpreter", "StopCodeInterpreterSession", "CodeInterpreterSession")
| STATS total_user_errors = sum(aws.bedrock_agentcore.metrics.UserErrors.sum), total_system_errors = sum(aws.bedrock_agentcore.metrics.SystemErrors.sum) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| EVAL total_errors = COALESCE(total_user_errors, TO_LONG(0)) + COALESCE(total_system_errors, TO_LONG(0))
| WHERE total_errors > 0

aws-bedrock-agentcore-code-interpreter-h.esql:
// Alert triggers when high execution duration is detected during AWS Bedrock AgentCore Code Interpreter operations.
//
// Code Interpreter executes code within secure, isolated sessions. High duration
// can indicate complex computations, resource constraints, or inefficient code.
//
// Duration measures the average execution time for code interpreter operations
// in milliseconds.
//
// High latency in code execution can impact:
// - Agent response times
// - User experience
// - Session timeouts
//
// The alert is grouped by cloud account, region, and resource.
//
// To adjust sensitivity, change the threshold (default: 30000ms = 30 seconds).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/code-interpreter-observability.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("InvokeCodeInterpreter", "CodeInterpreterSession")
| STATS avg_duration_ms = avg(aws.bedrock_agentcore.metrics.Duration.avg) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| WHERE avg_duration_ms > 30000

aws-bedrock-agentcore-code-interpreter-t.esql:
// Alert triggers when throttling occurs during AWS Bedrock AgentCore Code Interpreter operations.
//
// Code Interpreter enables agents to execute code within secure, isolated sessions.
// Throttling indicates that code execution requests are being rate-limited.
//
// Operations monitored:
// - StartCodeInterpreterSession: Session creation throttles
// - InvokeCodeInterpreter: Code execution throttles
// - StopCodeInterpreterSession: Session termination throttles
//
// Common causes of throttling:
// - High volume of code execution requests
// - Concurrent session limits exceeded
// - Compute resource constraints
//
// The alert is grouped by cloud account, region, and resource.
//
// To reduce alert noise, increase the threshold (e.g., `total_throttles > 10`).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/code-interpreter-observability.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("StartCodeInterpreterSession", "InvokeCodeInterpreter", "StopCodeInterpreterSession")
| STATS total_throttles = sum(aws.bedrock_agentcore.metrics.Throttles.sum) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| WHERE total_throttles > 0

aws-bedrock-agentcore-gateway-errors.esql:
// Alert triggers when errors occur during AWS Bedrock AgentCore Gateway invocations.
//
// Gateway provides a unified API endpoint that enables agents to securely connect
// to enterprise tools and external resources. It acts as a proxy that handles
// authentication, authorization, and routing of requests.
//
// This alert monitors both:
// - User errors (4xx): Client-side errors like invalid requests, unauthorized access
// - System errors (5xx): Server-side errors indicating infrastructure issues
//
// The alert is grouped by cloud account, region, and resource to pinpoint the
// specific gateway experiencing issues.
//
// To reduce alert noise, increase the threshold (e.g., `total_errors > 5`) to only
// alert on sustained error patterns.
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/observability-gateway-metrics.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation == "InvokeGateway"
| STATS total_user_errors = sum(aws.bedrock_agentcore.metrics.UserErrors.sum), total_system_errors = sum(aws.bedrock_agentcore.metrics.SystemErrors.sum) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| EVAL total_errors = COALESCE(total_user_errors, TO_LONG(0)) + COALESCE(total_system_errors, TO_LONG(0))
| WHERE total_errors > 0

aws-bedrock-agentcore-gateway-high-laten.esql:
// Alert triggers when high latency is detected during AWS Bedrock AgentCore Gateway invocations.
//
// Gateway serves as a unified API endpoint that enables agents to securely connect to
// enterprise tools and resources. High latency can indicate network issues, slow
// downstream services, or resource constraints.
//
// Latency measures the average time elapsed between receiving the gateway request
// and returning the response, measured in milliseconds.
//
// The alert is grouped by cloud account, region, and resource to pinpoint the
// specific gateway experiencing high latency.
//
// To adjust sensitivity, change the threshold in the WHERE clause (default: 5000ms = 5 seconds).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/observability-gateway-metrics.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation == "InvokeGateway"
| STATS avg_latency_ms = avg(aws.bedrock_agentcore.metrics.Latency.avg) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| WHERE avg_latency_ms > 5000

aws-bedrock-agentcore-gateway-throttles.esql:
// Alert triggers when throttling occurs during AWS Bedrock AgentCore Gateway invocations.
//
// Gateway throttling indicates that requests are being rate-limited due to exceeding
// allowed TPS (transactions per second) or quota limits. This can impact agent
// performance and user experience.
//
// Common causes of throttling:
// - High request volume exceeding service quotas
// - Burst traffic patterns
// - Insufficient provisioned capacity
//
// The alert is grouped by cloud account, region, and resource to identify
// which gateways are being throttled.
//
// To reduce alert noise, increase the threshold (e.g., `total_throttles > 10`).
// Consider requesting a service quota increase if sustained throttling occurs.
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/observability-gateway-metrics.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation == "InvokeGateway"
| STATS total_throttles = sum(aws.bedrock_agentcore.metrics.Throttles.sum) BY cloud.account.id, cloud.region, aws.dimensions.Resource
| WHERE total_throttles > 0

aws-bedrock-agentcore-identity-throttles.esql:
// Alert triggers when throttling occurs during AWS Bedrock AgentCore Identity operations.
//
// Identity service handles authentication and token management for agents.
// Throttling in identity operations can indicate:
// - Workload access token fetch throttles: Rate limiting on workload identity tokens
// - Resource access token fetch throttles: Rate limiting on OAuth2 token fetches
// - API key fetch throttles: Rate limiting on API key retrievals
//
// Token fetch throttling can prevent agents from accessing protected resources
// and may cause cascading failures in agent workflows.
//
// The alert is grouped by cloud account and region to identify affected environments.
//
// To reduce alert noise, increase the threshold (e.g., `total_throttles > 10`).

FROM metrics-aws_bedrock_agentcore.metrics-*
| STATS workload_throttles = sum(aws.bedrock_agentcore.metrics.WorkloadAccessTokenFetchThrottles.sum), resource_throttles = sum(aws.bedrock_agentcore.metrics.ResourceAccessTokenFetchThrottles.sum), apikey_throttles = sum(aws.bedrock_agentcore.metrics.ApiKeyFetchThrottles.sum) BY cloud.account.id, cloud.region
| EVAL total_throttles = COALESCE(workload_throttles, TO_LONG(0)) + COALESCE(resource_throttles, TO_LONG(0)) + COALESCE(apikey_throttles, TO_LONG(0))
| WHERE total_throttles > 0

aws-bedrock-agentcore-identity-token-fet.esql:
// Alert triggers when token fetch failures occur in AWS Bedrock AgentCore Identity operations.
//
// Identity service manages authentication and authorization for agents, including:
// - WorkloadAccessTokenFetch: Fetching tokens for workload identities
// - ResourceAccessTokenFetch: Fetching tokens for resource access (OAuth2)
//
// Token fetch failures indicate authentication issues that can prevent agents from
// accessing protected resources and downstream services. Common causes include:
// - Expired or invalid credentials
// - Network connectivity issues to identity providers
// - Misconfigured authentication settings
// - Rate limiting from identity providers
//
// The alert is grouped by cloud account and region to identify affected environments.
//
// To reduce alert noise, increase the threshold (e.g., `total_failures > 5`) to only
// alert on sustained failure patterns rather than transient authentication issues.
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/identity.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| STATS workload_failures = sum(aws.bedrock_agentcore.metrics.WorkloadAccessTokenFetchFailures.sum), resource_failures = sum(aws.bedrock_agentcore.metrics.ResourceAccessTokenFetchFailures.sum) BY cloud.account.id, cloud.region
| EVAL total_failures = COALESCE(workload_failures, TO_LONG(0)) + COALESCE(resource_failures, TO_LONG(0))
| WHERE total_failures > 0

aws-bedrock-agentcore-memory-errors.esql:
// Alert triggers when errors occur during AWS Bedrock AgentCore Memory operations.
//
// Memory enables agents to persist and retrieve contextual information across
// sessions, providing long-term memory capabilities. Operations include:
// - CreateEvent: Creates new memory events
// - RetrieveMemoryRecords: Retrieves stored memory records
// - ListEvents: Lists memory events
// - ListMemory: Lists available memory stores
// - LongTermMemoryProcessing: Background processing for long-term memory
// - Extraction/Consolidation: Memory optimization operations
//
// This alert monitors both user errors (4xx) and system errors (5xx).
//
// The alert is grouped by cloud account and region to identify affected environments.
//
// To reduce alert noise, increase the threshold (e.g., `total_errors > 5`).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/memory.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("CreateEvent", "RetrieveMemoryRecords", "ListEvents", "ListMemory", "LongTermMemoryProcessing", "Extraction", "Consolidation")
| STATS total_user_errors = sum(aws.bedrock_agentcore.metrics.UserErrors.sum), total_system_errors = sum(aws.bedrock_agentcore.metrics.SystemErrors.sum) BY cloud.account.id, cloud.region
| EVAL total_errors = COALESCE(total_user_errors, TO_LONG(0)) + COALESCE(total_system_errors, TO_LONG(0))
| WHERE total_errors > 0

aws-bedrock-agentcore-memory-high-latenc.esql:
// Alert triggers when high latency is detected during AWS Bedrock AgentCore Memory operations.
//
// Memory latency directly impacts agent response times, especially for operations
// that require retrieving contextual information before responding.
//
// The alert is grouped by cloud account, region, and operation to pinpoint
// specific memory operations experiencing high latency.
//
// To adjust sensitivity, change the threshold in the WHERE clause (default: 3000ms = 3 seconds).
// For more details, see: https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/memory.html

FROM metrics-aws_bedrock_agentcore.metrics-*
| WHERE aws.dimensions.Operation IN ("CreateEvent", "RetrieveMemoryRecords", "ListEvents", "ListMemory")
| STATS avg_latency_ms = avg(aws.bedrock_agentcore.metrics.Latency.avg) BY cloud.account.id, cloud.region, aws.dimensions.Operation
| WHERE avg_latency_ms > 3000

azure_activity_otel-change-storm.esql:
FROM logs-azure.activity.otel-*
// Restrict to Azure Activity Logs (Administrative category)
| WHERE azure.category IS NOT NULL
| WHERE azure.category == "Administrative"
// Mutations: write, delete, action operations (exclude read)
| WHERE azure.operation.name LIKE "*WRITE*" OR azure.operation.name LIKE "*DELETE*" OR azure.operation.name LIKE "*ACTION*"
// Exclude in-progress
| WHERE azure.result.type NOT IN ("Start", "Started")
// Derive caller for grouping
| EVAL caller = COALESCE(user.id, azure.identity.authorization.evidence.principal.id, "unknown")
// Aggregate total mutation count per caller — high counts indicate change storm
| STATS mutation_count = COUNT(*), operations = VALUES(azure.operation.name) BY caller
// Threshold: adjust based on normal baseline (e.g. 50+ mutations in 15m may indicate runaway automation)
| WHERE mutation_count >= 50
| SORT mutation_count DESC
| LIMIT 10

azure_activity_otel-failed-administrativ.esql:
FROM logs-azure.activity.otel-*
// Restrict to Azure Activity Logs (Administrative category)
| WHERE azure.category IS NOT NULL
| WHERE azure.category == "Administrative"
// Capture both Failure and Failed result types (Azure uses inconsistent casing)
| WHERE azure.result.type IN ("Failure", "Failed")
// Derive caller for grouping (user.id or principal ID)
| EVAL caller = COALESCE(user.id, azure.identity.authorization.evidence.principal.id, "unknown")
// Aggregate by operation and caller for context; adjust minimum count to reduce noise
| STATS failed_count = COUNT(*), sample_timestamps = VALUES(@timestamp) BY azure.operation.name, caller, network.peer.address
// Minimum failures to alert — tune based on environment noise
| WHERE failed_count >= 3
| SORT failed_count DESC
| LIMIT 20

azure_activity_otel-resource-health-degr.esql:
FROM logs-azure.activity.otel-*
// Restrict to Azure Activity Logs (ResourceHealth category)
| WHERE azure.category IS NOT NULL
| WHERE azure.category == "ResourceHealth"
// Current state indicates Unavailable or Degraded — resources needing attention
| WHERE azure.resourcehealth.state IN ("Unavailable", "Degraded")
// Optional: filter by cause (PlatformInitiated vs UserInitiated) — remove to include all
| STATS event_count = COUNT(*), health_type = VALUES(azure.resourcehealth.type), cause = VALUES(azure.resourcehealth.cause) BY cloud.resource_id, azure.resourcehealth.title
| SORT event_count DESC
| LIMIT 20

azure_activity_otel-role-assignment-writ.esql:
FROM logs-azure.activity.otel-*
// Restrict to Azure Activity Logs
| WHERE azure.category IS NOT NULL
| WHERE azure.category == "Administrative"
// Role assignment writes indicate privilege changes — potential escalation
| WHERE azure.operation.name LIKE "*ROLEASSIGNMENTS*WRITE*" OR azure.operation.name LIKE "*ROLEASSIGNMENT*WRITE*"
// Derive caller for grouping (falls back to principal ID for service principals / managed identities)
| EVAL caller = COALESCE(user.id, azure.identity.authorization.evidence.principal.id, "unknown")
// Include both success and failure — the attempt is the security signal
| STATS assignment_count = COUNT(*), roles = VALUES(azure.identity.authorization.evidence.role) BY caller, azure.identity.authorization.evidence.principal.type, network.peer.address
| SORT assignment_count DESC
| LIMIT 20

azure_activity_otel-sensitive-key-access.esql:
FROM logs-azure.activity.otel-*
// Restrict to Azure Activity Logs
| WHERE azure.category IS NOT NULL
| WHERE azure.category == "Administrative"
// listKeys/action exposes storage account keys — high-privilege, security-sensitive
| WHERE azure.operation.name LIKE "*LISTKEYS*" OR azure.operation.name LIKE "*LISTKEY*"
// Derive caller for grouping (falls back to principal ID for service principals / managed identities)
| EVAL caller = COALESCE(user.id, azure.identity.authorization.evidence.principal.id, "unknown")
// Include both success and failure — attempted access is the signal
| STATS access_count = COUNT(*), result_types = VALUES(azure.result.type) BY caller, azure.identity.authorization.evidence.principal.type, network.peer.address, cloud.resource_id
| SORT access_count DESC
| LIMIT 20

azure_activity_otel-service-health-incid.esql:
FROM logs-azure.activity.otel-*
// Restrict to Azure Activity Logs (ServiceHealth category)
| WHERE azure.category IS NOT NULL
| WHERE azure.category == "ServiceHealth"
// Incident type indicates active Azure platform outage (vs Maintenance, Informational)
| WHERE azure.servicehealth.incident.type == "Incident"
// Active state — incident in progress; optionally include Resolved for awareness
| WHERE azure.servicehealth.state == "Active"
// Exclude synthetic test events if present
| WHERE COALESCE(azure.servicehealth.is_synthetic, false) == false
| STATS event_count = COUNT(*), services = VALUES(azure.servicehealth.service), regions = VALUES(azure.servicehealth.region) BY azure.servicehealth.tracking.id, azure.servicehealth.title
| SORT event_count DESC
| LIMIT 20

azure_ai_foundry-latency-spike.esql:
// Alert triggers when the response latency exceeds the recommended threshold value {5000ms} within the look back time window.
// The alert is grouped by Model Deployment Name.
// You can adjust the threshold value by modifying the time_to_response in the WHERE clause, which is specified in milliseconds.
FROM metrics-azure.ai_foundry-default
| KEEP azure.ai_foundry.time_to_response.avg, azure.dimensions.model_deployment_name, @timestamp
| WHERE azure.dimensions.model_deployment_name IS NOT NULL
| STATS time_to_response = MAX(azure.ai_foundry.time_to_response.avg) BY azure.dimensions.model_deployment_name
| WHERE time_to_response > 5000
| EVAL time_to_response = ROUND(time_to_response, 2)
| SORT time_to_response DESC

azure_ai_foundry-model-availability.esql:
// Alert triggers when the model availability is less than the recommended threshold value {99%} within the look back time window.
// The alert is grouped by Model Deployment Name.
// You can adjust the threshold value by modifying the model_availability in the WHERE clause, which is specified in percent.
FROM metrics-azure.ai_foundry-default
| KEEP azure.ai_foundry.model_availability_rate.avg, azure.dimensions.model_deployment_name, @timestamp
| WHERE azure.dimensions.model_deployment_name IS NOT NULL
| STATS model_availability = MIN(azure.ai_foundry.model_availability_rate.avg) * 100 BY azure.dimensions.model_deployment_name
| WHERE model_availability < 99
| EVAL model_availability = ROUND(model_availability, 2)
| SORT model_availability ASC

azure_ai_foundry-provisioned-utilization.esql:
// Alert triggers when the provisioned utilization exceeds the recommended threshold value {85%} within the look back time window.
// The alert is grouped by Model Deployment Name.
// You can adjust the threshold value by modifying the provisioned_utilization in the WHERE clause, which is specified in percent.
FROM metrics-azure.ai_foundry-default
| KEEP azure.ai_foundry.provisioned_utilization.avg, azure.dimensions.model_deployment_name, @timestamp
| WHERE azure.dimensions.model_deployment_name IS NOT NULL
| STATS provisioned_utilization = MAX(azure.ai_foundry.provisioned_utilization.avg) * 100 BY azure.dimensions.model_deployment_name
| WHERE provisioned_utilization > 85
| EVAL provisioned_utilization = ROUND(provisioned_utilization, 2)
| SORT provisioned_utilization DESC

azure_openai-latency-spike.esql:
// Alert triggers when the response latency exceeds the recommended threshold value {5000ms} within the look back time window.
// The alert is grouped by Model Deployment Name.
// You can adjust the threshold value by modifying the time_to_response in the WHERE clause, which is specified in milliseconds.
FROM metrics-azure.open_ai-default
| KEEP azure.open_ai.time_to_response.avg, azure.dimensions.model_deployment_name, @timestamp
| WHERE azure.dimensions.model_deployment_name IS NOT NULL
| STATS time_to_response = MAX(azure.open_ai.time_to_response.avg) BY azure.dimensions.model_deployment_name
| WHERE time_to_response > 5000
| EVAL time_to_response = ROUND(time_to_response, 2)
| SORT time_to_response DESC

azure_openai-provisioned-utilization.esql:
// Alert triggers when the provisioned utilization exceeds the recommended threshold value {85%} within the look back time window.
// The alert is grouped by Model Deployment Name.
// You can adjust the threshold value by modifying the provisioned_utilization in the WHERE clause, which is specified in percent.
FROM metrics-azure.open_ai-default
| KEEP azure.open_ai.provisioned_managed_utilization_v2.avg, azure.dimensions.model_deployment_name, @timestamp
| WHERE azure.dimensions.model_deployment_name IS NOT NULL
| STATS provisioned_utilization = MAX(azure.open_ai.provisioned_managed_utilization_v2.avg) * 100 BY azure.dimensions.model_deployment_name
| WHERE provisioned_utilization > 85
| EVAL provisioned_utilization = ROUND(provisioned_utilization, 2)
| SORT provisioned_utilization DESC

azure_openai-quota-error-rates.esql:
// Alert triggers when the quota_error count is greater than recommended threshold value {5} within the look back time window.
// The alert is grouped by Model Deployment Name.
// You can adjust the threshold value by modifying the quota_error count in the WHERE clause.
FROM logs-azure_openai.logs-default
| KEEP http.response.status_code, azure.dimensions.model_deployment_name, @timestamp
| WHERE azure.dimensions.model_deployment_name IS NOT NULL
| WHERE http.response.status_code == 429
| STATS quota_error = COUNT(*) BY azure.dimensions.model_deployment_name
| WHERE quota_error > 5
| SORT quota_error DESC

haproxy_otel-backend-no-active-servers.esql:
FROM metrics-haproxyreceiver.otel-*
// Scope to backend aggregates (not frontends or individual servers)
| WHERE haproxy.service_name == "BACKEND"
// Exclude stats backend — it has no upstream servers by design
| WHERE haproxy.proxy_name != "stats"
// Aggregate minimum active count per backend over the time window
| STATS min_active = MIN(haproxy.active) BY haproxy.proxy_name, haproxy.addr
// Alert when any backend has zero active servers
| WHERE min_active < 1
| EVAL alert_key = CONCAT(TO_STRING(haproxy.proxy_name), "::", COALESCE(TO_STRING(haproxy.addr), ""))
| LIMIT 50

ibmmq_otel-cpu-load-high.esql:
TS metrics-ibmmq.otel-*
| STATS cpu_load_5m = MAX(AVG_OVER_TIME(ibmmq_qmgr_cpu_load_five_minute_average_percentage))
    BY attributes.qmgr
// Alert when the 5-minute CPU load average exceeds 85%
// < 70% is healthy; 70-85% is warning; > 85% is critical
// High CPU load degrades message throughput and increases latency
// Adjust threshold based on your host capacity and co-located workloads
| WHERE cpu_load_5m IS NOT NULL AND cpu_load_5m > 85

ibmmq_otel-expired-messages.esql:
TS metrics-ibmmq.otel-*
| STATS expired_rate = SUM(RATE(ibmmq_qmgr_expired_message_total))
    BY attributes.qmgr
// Alert when messages are expiring before being consumed
// Any non-zero expiration rate indicates consumers are falling behind
// or message TTL settings are too aggressive
// Adjust threshold based on expected message expiration patterns
| WHERE expired_rate IS NOT NULL AND expired_rate > 0

ibmmq_otel-failed-connections.esql:
TS metrics-ibmmq.otel-*
| STATS
    failed_conns = SUM(RATE(ibmmq_qmgr_failed_mqconn_mqconnx_total)),
    failed_opens = SUM(RATE(ibmmq_qmgr_failed_mqopen_total))
    BY attributes.qmgr
| EVAL total_failed_access = COALESCE(failed_conns, 0) + COALESCE(failed_opens, 0)
// Alert when connection or object-open failures are detected
// Failures indicate authentication problems, resource exhaustion,
// or network issues between clients and the queue manager
// Adjust threshold based on your environment
| WHERE total_failed_access > 0

ibmmq_otel-failed-message-operations.esql:
TS metrics-ibmmq.otel-*
| STATS
    failed_puts = SUM(RATE(ibmmq_qmgr_failed_mqput_total)),
    failed_put1s = SUM(RATE(ibmmq_qmgr_failed_mqput1_total)),
    failed_gets = SUM(RATE(ibmmq_qmgr_failed_mqget_total))
    BY attributes.qmgr
| EVAL total_failed_msg_ops = COALESCE(failed_puts, 0) + COALESCE(failed_put1s, 0) + COALESCE(failed_gets, 0)
// Alert when failed put or get operations are detected
// In a healthy system, these should all be at zero rate
// Failures indicate queue full, auth issues, or application errors
// Adjust threshold based on expected traffic volume
| WHERE total_failed_msg_ops > 0

ibmmq_otel-fdc-files-increasing.esql:
TS metrics-ibmmq.otel-*
| STATS fdc_change = SUM(DELTA(ibmmq_qmgr_fdc_files))
    BY attributes.qmgr
// Alert when new FDC (First Failure Data Capture) files are generated
// FDC files indicate internal queue manager errors
// Any increase is significant and requires immediate investigation
| WHERE fdc_change IS NOT NULL AND fdc_change > 0

ibmmq_otel-high-log-write-latency.esql:
TS metrics-ibmmq.otel-*
| STATS log_latency_s = MAX(AVG_OVER_TIME(ibmmq_qmgr_log_write_latency_seconds))
    BY attributes.qmgr
// Alert when average log write latency exceeds 5ms (0.005s)
// Sub-millisecond is healthy; > 1ms is warning; > 10ms is critical
// Persistent messages require synchronous log writes, so latency
// directly governs end-to-end message throughput
// Adjust threshold based on your performance requirements
| WHERE log_latency_s IS NOT NULL AND log_latency_s > 0.005

ibmmq_otel-high-rollback-ratio.esql:
TS metrics-ibmmq.otel-*
| STATS
    commit_rate = SUM(RATE(ibmmq_qmgr_commit_total)),
    rollback_rate = SUM(RATE(ibmmq_qmgr_rollback_total))
    BY attributes.qmgr
// Require a minimum commit rate to avoid false positives on idle queue managers
| WHERE commit_rate IS NOT NULL AND commit_rate > 0
    AND rollback_rate IS NOT NULL
| EVAL rollback_pct = ROUND(rollback_rate / (commit_rate + rollback_rate) * 100.0, 2)
// Alert when rollback rate exceeds 5% of total transactions
// < 1% is healthy; 1-5% is warning; > 5% is critical
// High rollback ratios indicate poison messages, processing failures,
// or resource contention causing transaction failures
// Adjust threshold and minimum commit rate for your workload
| WHERE rollback_pct > 5.0

ibmmq_otel-log-filesystem-critically-low.esql:
TS metrics-ibmmq.otel-*
| STATS log_fs_free_pct = MAX(LAST_OVER_TIME(ibmmq_qmgr_log_file_system_free_space_percentage))
    BY attributes.qmgr
// Alert when log filesystem free space drops below 10%
// Log filesystem exhaustion halts all transactional operations
// Adjust threshold based on your capacity planning requirements
| WHERE log_fs_free_pct IS NOT NULL AND log_fs_free_pct < 10

ibmmq_otel-queue-manager-filesystem-low.esql:
TS metrics-ibmmq.otel-*
| STATS qmgr_fs_free_pct = MAX(LAST_OVER_TIME(ibmmq_qmgr_queue_manager_file_system_free_space_percentage))
    BY attributes.qmgr
// Alert when queue manager filesystem free space drops below 20%
// The queue manager filesystem stores configuration and queue data
// Adjust threshold based on your capacity planning requirements
| WHERE qmgr_fs_free_pct IS NOT NULL AND qmgr_fs_free_pct < 20

influxdb_otel-cache-write-errors.esql:
FROM metrics-influxdb.otel-*
// Cache write errors counter (cumulative)
| WHERE COALESCE(metrics.storage_cache_writes_err, storage_cache_writes_err) IS NOT NULL
// Detect increase in errors over the window
| STATS min_err = MIN(COALESCE(metrics.storage_cache_writes_err, storage_cache_writes_err)),
    max_err = MAX(COALESCE(metrics.storage_cache_writes_err, storage_cache_writes_err))
  BY host.name
| EVAL error_increase = max_err - min_err
// Alert when any new cache write errors occurred
| WHERE error_increase > 0

influxdb_otel-compaction-queue-backlog.esql:
FROM metrics-influxdb.otel-*
// Compactions waiting to run (gauge)
| WHERE COALESCE(metrics.storage_compactions_queued, storage_compactions_queued) IS NOT NULL
// Get max queue depth per host and compaction level
| STATS max_queued = MAX(COALESCE(metrics.storage_compactions_queued, storage_compactions_queued))
  BY host.name, COALESCE(attributes.level, "unknown")
// Alert when compaction queue exceeds threshold (e.g. 10)
// Adjust for your environment
| WHERE max_queued >= 10

influxdb_otel-go-goroutine-leak.esql:
FROM metrics-influxdb.otel-*
// Go runtime goroutine count (gauge)
| WHERE COALESCE(metrics.go_goroutines, go_goroutines) IS NOT NULL
// Get max goroutine count per host over the window
| STATS max_goroutines = MAX(COALESCE(metrics.go_goroutines, go_goroutines))
  BY host.name
// Alert when goroutines exceed threshold (e.g. 10000)
// High count may indicate leak; adjust for your baseline
| WHERE max_goroutines > 10000

influxdb_otel-http-api-high-error-rate.esql:
FROM metrics-influxdb.otel-*
// HTTP API requests with response code/status
| WHERE COALESCE(metrics.http_api_requests_total, http_api_requests_total) IS NOT NULL
// Aggregate total and error counts per host (status != 2XX = errors)
| STATS total = SUM(COALESCE(metrics.http_api_requests_total, http_api_requests_total)),
    errors = SUM(COALESCE(metrics.http_api_requests_total, http_api_requests_total))
      WHERE COALESCE(attributes.status, status) != "2XX"
  BY host.name
// Minimum sample size to avoid noisy low-traffic hosts
| WHERE total > 10
// Calculate error rate as percentage
| EVAL error_rate_pct = ROUND(errors / total * 100.0, 2)
// Alert threshold: adjust for your environment (e.g. 5%)
| WHERE error_rate_pct > 5.0
| SORT error_rate_pct DESC
| LIMIT 10

influxdb_otel-query-controller-saturated.esql:
FROM metrics-influxdb.otel-*
// Query controller queueing and memory budget
| WHERE COALESCE(metrics.qc_queueing_active, qc_queueing_active) IS NOT NULL
    OR COALESCE(metrics.qc_memory_unused_bytes, qc_memory_unused_bytes) IS NOT NULL
// Get latest values per host (gauges)
| STATS max_queueing = MAX(COALESCE(metrics.qc_queueing_active, qc_queueing_active)),
    min_memory_unused = MIN(COALESCE(metrics.qc_memory_unused_bytes, qc_memory_unused_bytes))
  BY host.name
// Alert when queueing is high (>= 5) or memory budget exhausted (< 10MB)
// Adjust thresholds for your workload
| WHERE max_queueing >= 5 OR (min_memory_unused IS NOT NULL AND min_memory_unused < 10485760)

influxdb_otel-task-execution-failures.esql:
FROM metrics-influxdb.otel-*
// Task scheduler execution failure counter (cumulative)
| WHERE COALESCE(metrics.task_scheduler_total_execute_failure, task_scheduler_total_execute_failure) IS NOT NULL
// Detect increase in failures over the window
| STATS min_fail = MIN(COALESCE(metrics.task_scheduler_total_execute_failure, task_scheduler_total_execute_failure)),
    max_fail = MAX(COALESCE(metrics.task_scheduler_total_execute_failure, task_scheduler_total_execute_failure))
  BY host.name
| EVAL failure_increase = max_fail - min_fail
// Alert when any new task execution failures occurred
| WHERE failure_increase > 0

influxdb_otel-wal-write-errors.esql:
FROM metrics-influxdb.otel-*
// WAL write errors counter (cumulative)
| WHERE COALESCE(metrics.storage_wal_writes_err, storage_wal_writes_err) IS NOT NULL
// Detect increase in errors over the window
| STATS min_err = MIN(COALESCE(metrics.storage_wal_writes_err, storage_wal_writes_err)),
    max_err = MAX(COALESCE(metrics.storage_wal_writes_err, storage_wal_writes_err))
  BY host.name
| EVAL error_increase = max_err - min_err
// Alert when any new WAL write errors occurred
| WHERE error_increase > 0

influxdb_otel-writer-timeouts.esql:
FROM metrics-influxdb.otel-*
// Storage writer timeout counter (cumulative)
| WHERE COALESCE(metrics.storage_writer_timeouts, storage_writer_timeouts) IS NOT NULL
// Detect increase in timeouts over the window
| STATS min_timeout = MIN(COALESCE(metrics.storage_writer_timeouts, storage_writer_timeouts)),
    max_timeout = MAX(COALESCE(metrics.storage_writer_timeouts, storage_writer_timeouts))
  BY host.name
| EVAL timeout_increase = max_timeout - min_timeout
// Alert when any new writer timeouts occurred
| WHERE timeout_increase > 0

kafka_otel-broker-count-low.esql:
FROM metrics-kafkametricsreceiver.otel-*
// Cluster-level broker count (no attributes)
| WHERE kafka.brokers IS NOT NULL
| STATS latest_brokers = MAX(kafka.brokers)
// Threshold: alert when broker count < expected minimum.
// Customise the value below for your cluster (e.g. 2 for HA, 1 for any loss)
| WHERE latest_brokers < 2

kafka_otel-under-replicated-partitions.esql:
FROM metrics-kafkametricsreceiver.otel-*
// Partition metrics: replicas vs in-sync replicas
| WHERE kafka.partition.replicas IS NOT NULL AND kafka.partition.replicas_in_sync IS NOT NULL
| STATS replicas = MAX(kafka.partition.replicas),
    replicas_in_sync = MAX(kafka.partition.replicas_in_sync)
  BY attributes.topic, attributes.partition
// Alert when any replica is out of sync (replication degraded)
// Indicates broker failures, network issues, or overloaded followers
| WHERE replicas > replicas_in_sync
| SORT replicas_in_sync ASC

kubernetes_otel-node-cpu-saturation.esql:
TS metrics-kubeletstatsreceiver.otel-*, metrics-k8sclusterreceiver.otel-*
| WHERE k8s.node.name IS NOT NULL
    AND (k8s.node.cpu.usage IS NOT NULL OR k8s.node.allocatable_cpu IS NOT NULL)
| STATS avg_cpu = AVG(k8s.node.cpu.usage),
    allocatable_cpu = MAX(k8s.node.allocatable_cpu)
    BY k8s.node.name
| EVAL cpu_utilization = avg_cpu / allocatable_cpu
// Alert when average CPU usage exceeds 90% of allocatable capacity.
// Adjust the threshold to suit your environment.
//
// Requires k8s.node.allocatable_cpu from k8sclusterreceiver.
// This metric is controlled by allocatable_types_to_report config
// option, which must include "cpu". Not enabled by default.
// If unavailable, replace the utilization check with a static
// threshold on avg_cpu, e.g.: WHERE avg_cpu > 3.6
| WHERE cpu_utilization > 0.9
| KEEP k8s.node.name, avg_cpu, allocatable_cpu, cpu_utilization

kubernetes_otel-node-memory-saturation.esql:
TS metrics-kubeletstatsreceiver.otel-*, metrics-k8sclusterreceiver.otel-*
| WHERE k8s.node.name IS NOT NULL
    AND (k8s.node.memory.working_set IS NOT NULL OR k8s.node.allocatable_memory IS NOT NULL)
| STATS avg_memory = AVG(k8s.node.memory.working_set),
    allocatable_memory = MAX(k8s.node.allocatable_memory)
    BY k8s.node.name
| EVAL memory_utilization = avg_memory / allocatable_memory
// Alert when average memory working set exceeds 85% of allocatable.
// Adjust the threshold to suit your environment.
//
// Requires k8s.node.allocatable_memory from k8sclusterreceiver.
// This metric is controlled by allocatable_types_to_report config
// option, which must include "memory". Not enabled by default.
// If unavailable, replace the utilization check with a static
// threshold on avg_memory, e.g.: WHERE avg_memory > 13743895347
| WHERE memory_utilization > 0.85
| EVAL avg_memory_gib = ROUND(avg_memory / 1073741824, 2)
| KEEP k8s.node.name, avg_memory_gib, allocatable_memory, memory_utilization

kubernetes_otel-pod-crashloopbackoff.esql:
TS metrics-k8sclusterreceiver.otel-*
| STATS restarts = MAX(k8s.container.restarts)
    BY k8s.pod.name, k8s.container.name, k8s.namespace.name
// k8s.container.restarts is a gauge reflecting recent restarts.
// The value resets to 0 when kubelet prunes dead containers,
// so > 0 reliably means "restarting in the recent past".
// Combined with a 15m window and alertDelay of 3, this
// catches sustained crash loops without one-off false positives.
| WHERE restarts > 0
| SORT restarts DESC
| KEEP k8s.namespace.name, k8s.pod.name, k8s.container.name, restarts
| LIMIT 50

mongodb_otel-global-lock-contention.esql:
TS metrics-mongodbreceiver.otel-default
// Scope to MongoDB OTel metrics
| WHERE data_stream.dataset == "mongodbreceiver.otel"
| WHERE metrics.mongodb.global_lock.time IS NOT NULL
// Rate of global lock time held (ms/sec); high rate indicates contention
| STATS lock_time_rate = SUM(RATE(metrics.mongodb.global_lock.time)) BY resource.attributes.server.address
// Alert when lock held >500ms/sec on average (adjust for your workload)
| WHERE lock_time_rate > 500
| SORT lock_time_rate DESC
| LIMIT 20

mongodb_otel-high-cursor-count.esql:
TS metrics-mongodbreceiver.otel-default
// Scope to MongoDB OTel metrics
| WHERE data_stream.dataset == "mongodbreceiver.otel"
| WHERE metrics.mongodb.cursor.count IS NOT NULL
// Current open cursor count (gauge)
| STATS cursors = MAX(LAST_OVER_TIME(metrics.mongodb.cursor.count)) BY resource.attributes.server.address
// Alert when cursor count exceeds threshold (possible cursor leak; adjust 1000 for your workload)
| WHERE cursors > 1000
| SORT cursors DESC
| LIMIT 20

mongodb_otel-high-memory-usage.esql:
TS metrics-mongodbreceiver.otel-default
// Scope to MongoDB OTel metrics
| WHERE data_stream.dataset == "mongodbreceiver.otel"
| WHERE metrics.mongodb.memory.usage IS NOT NULL AND attributes.type == "resident"
// Resident memory is server-wide but emitted per database; use MAX to avoid double-counting
| STATS resident_bytes = MAX(LAST_OVER_TIME(metrics.mongodb.memory.usage)) BY resource.attributes.server.address
// Alert when resident memory exceeds 4GB (adjust for your host RAM)
| WHERE resident_bytes > 4294967296
| SORT resident_bytes DESC
| LIMIT 20

mongodb_otel-high-session-count.esql:
TS metrics-mongodbreceiver.otel-default
// Scope to MongoDB OTel metrics
| WHERE data_stream.dataset == "mongodbreceiver.otel"
| WHERE metrics.mongodb.session.count IS NOT NULL
// Current active session count (gauge)
| STATS sessions = MAX(LAST_OVER_TIME(metrics.mongodb.session.count)) BY resource.attributes.server.address
// Alert when session count exceeds threshold (possible pool misconfiguration; adjust 500 for your setup)
| WHERE sessions > 500
| SORT sessions DESC
| LIMIT 20

nginx-active-connections-high.esql:
FROM logs-myservicereceiver.otel-*
// Flag each log entry as an error or not
| EVAL is_error = CASE(log.level == "error", 1, 0)
// Aggregate total logs and error count per service
| STATS total = COUNT(*), errors = SUM(is_error) BY service.name
// Minimum sample size to avoid noisy low-traffic services
// Adjust this threshold based on expected traffic volume
| WHERE total > 50
// Calculate error rate as a percentage
| EVAL error_rate_pct = ROUND(errors / total * 100.0, 2)
// Alert threshold: adjust this to tune sensitivity
| WHERE error_rate_pct > 5.0
| SORT error_rate_pct DESC
| LIMIT 10

nginx_otel-dropped-connections.esql:
FROM metrics-nginxreceiver.otel-*
// Filter to connection counter documents (exclude gauge docs with state attribute)
| WHERE state IS NULL
// Cast counters to long for aggregation support
| EVAL accepted = TO_LONG(nginx.connections_accepted), handled = TO_LONG(nginx.connections_handled)
// Compute delta over the time window per host
| STATS max_accepted = MAX(accepted), min_accepted = MIN(accepted), max_handled = MAX(handled), min_handled = MIN(handled) BY host.name
// Calculate new connections accepted vs handled in this window
| EVAL delta_accepted = max_accepted - min_accepted, delta_handled = max_handled - min_handled
| EVAL dropped = delta_accepted - delta_handled
// Alert when any connections were dropped
| WHERE dropped > 0
| SORT dropped DESC
| LIMIT 10

nginx_otel-error-log-spike.esql:
FROM logs-nginx.error.otel-*
// Filter to severe log entries only
| WHERE log.level IN ("error", "crit", "alert", "emerg")
// Count error entries per host
| STATS error_count = COUNT(*) BY host.name
// Alert when error count exceeds threshold in the time window
// Adjust threshold based on expected baseline error volume
| WHERE error_count > 50
| SORT error_count DESC
| LIMIT 10

nginx_otel-high-4xx-error-rate.esql:
FROM logs-nginx.access.otel-*
// Flag each access log entry as a client error (4xx) or not
| EVAL is_4xx = CASE(http.response.status_code >= 400 AND http.response.status_code < 500, 1, 0)
// Aggregate total requests and 4xx count per NGINX host
| STATS total = COUNT(*), errors_4xx = SUM(is_4xx) BY host.name
// Minimum sample size to avoid noisy low-traffic hosts
| WHERE total > 50
// Calculate 4xx error rate as a percentage
| EVAL error_rate_pct = ROUND(TO_DOUBLE(errors_4xx) / TO_DOUBLE(total) * 100.0, 2)
// Alert threshold: 15% is a reasonable starting point for client errors
| WHERE error_rate_pct > 15.0
| SORT error_rate_pct DESC
| LIMIT 10

nginx_otel-high-5xx-error-rate.esql:
FROM logs-nginx.access.otel-*
// Flag each access log entry as a server error (5xx) or not
| EVAL is_5xx = CASE(http.response.status_code >= 500, 1, 0)
// Aggregate total requests and 5xx count per NGINX host
| STATS total = COUNT(*), errors_5xx = SUM(is_5xx) BY host.name
// Minimum sample size to avoid noisy low-traffic hosts
| WHERE total > 50
// Calculate 5xx error rate as a percentage
| EVAL error_rate_pct = ROUND(TO_DOUBLE(errors_5xx) / TO_DOUBLE(total) * 100.0, 2)
// Alert threshold: adjust to tune sensitivity
| WHERE error_rate_pct > 5.0
| SORT error_rate_pct DESC
| LIMIT 10

nginx_otel-high-active-connections.esql:
FROM metrics-nginxreceiver.otel-*
// Filter to active connection state gauges
| WHERE state == "active"
// Aggregate active connections per host
| STATS avg_active = AVG(nginx.connections_current), max_active = MAX(nginx.connections_current), sample_count = COUNT(*) BY host.name
// Require minimum samples to avoid false positives during startup
| WHERE sample_count >= 3
// Alert when average active connections exceed capacity threshold
// Adjust threshold based on your NGINX worker_connections setting
| WHERE avg_active > 256
| SORT avg_active DESC
| LIMIT 10

oracle_otel-dml-lock-utilisation-high.esql:
FROM metrics-oracledbreceiver.otel-*
// DML locks usage and limit are in separate TSDB document groups; aggregate across time window
| STATS usage = MAX(oracledb.dml_locks.usage),
        limit_val = MAX(oracledb.dml_locks.limit)
        BY oracledb.instance.name, host.name
// Exclude unlimited (-1)
| WHERE limit_val > 0
// Utilisation > 85% precedes lock-related errors and transaction queuing
// Adjust threshold to tune sensitivity
| EVAL utilisation_pct = ROUND(usage * 100.0 / limit_val, 1)
| WHERE utilisation_pct > 85
| SORT utilisation_pct DESC

oracle_otel-enqueue-deadlocks-detected.esql:
TS metrics-oracledbreceiver.otel-*
// enqueue_deadlocks is a cumulative counter; INCREASE gives new deadlocks in window
| WHERE oracledb.enqueue_deadlocks IS NOT NULL
| STATS delta = SUM(INCREASE(oracledb.enqueue_deadlocks))
        BY oracledb.instance.name, host.name
// Alert on any increase — deadlocks cause ORA-00060 and rolled-back transactions
// INCREASE handles counter resets on instance restart
| WHERE delta > 0
| SORT delta DESC

oracle_otel-session-utilisation-high.esql:
FROM metrics-oracledbreceiver.otel-*
// Sessions usage is split by session_type/session_status; limit is separate document group
// First aggregate per-timestamp to get total sessions at each scrape point
| STATS sessions_at_ts = SUM(oracledb.sessions.usage),
        limit_val = MAX(oracledb.sessions.limit)
        BY @timestamp, oracledb.instance.name, host.name
// Then take peak sessions across the time window
| STATS peak_sessions = MAX(sessions_at_ts),
        limit_val = MAX(limit_val)
        BY oracledb.instance.name, host.name
| WHERE limit_val > 0
// Utilisation threshold: 85% — approaching session limit prevents new connections
// Adjust threshold to tune sensitivity
| EVAL utilisation_pct = ROUND(peak_sessions * 100.0 / limit_val, 1)
| WHERE utilisation_pct > 85
| SORT utilisation_pct DESC

oracle_otel-transaction-limit-utilisatio.esql:
FROM metrics-oracledbreceiver.otel-*
// Transaction usage and limit are in separate TSDB document groups; aggregate across time window
| STATS usage = MAX(oracledb.transactions.usage),
        limit_val = MAX(oracledb.transactions.limit)
        BY oracledb.instance.name, host.name
// Exclude unlimited (-1)
| WHERE limit_val > 0
// Utilisation > 85% — transaction limit exhaustion prevents new transactions
// Adjust threshold to tune sensitivity
| EVAL utilisation_pct = ROUND(usage * 100.0 / limit_val, 1)
| WHERE utilisation_pct > 85
| SORT utilisation_pct DESC

otel-collector-internal-telemetry-otel-e.esql:
// Alert when the OpenTelemetry Collector reports non-zero rate of failed log record exports.
//
// metrics.otelcol_exporter_send_failed_log_records is a cumulative counter; RATE() yields
// per-bucket increases. TS is used for time-series metrics (counter resets handled by the TS pipeline).
//
// Scope: metrics-collectortelemetry* and collectortelemetry.otel dataset to avoid mixing with
// unrelated metrics-* streams.
//
// Grouping: service.name and service.instance.id help identify which collector instance fails.
//
// Tuning: raise the threshold (e.g. failed_log_records_rate > N) or increase alert delay
// to reduce noise from brief blips.
//
TS metrics-collectortelemetry*
| WHERE data_stream.dataset == "collectortelemetry.otel"
| STATS failed_log_records_rate = SUM(RATE(metrics.otelcol_exporter_send_failed_log_records)) BY service.name, service.instance.id
| WHERE failed_log_records_rate > 0
| SORT failed_log_records_rate DESC

// Alert when the OpenTelemetry Collector reports non-zero rate of failed metric point exports.
//
// metrics.otelcol_exporter_send_failed_metric_points is a cumulative counter; RATE() yields
// per-bucket increases. TS is used for time-series metrics (counter resets handled by the TS pipeline).
//
// Scope: metrics-collectortelemetry* and collectortelemetry.otel dataset to avoid mixing with
// unrelated metrics-* streams.
//
// Grouping: service.name and service.instance.id help identify which collector instance fails.
//
// Tuning: raise the threshold (e.g. failed_metric_points_rate > N) or increase alert delay
// to reduce noise from brief blips.
//
TS metrics-collectortelemetry*
| WHERE data_stream.dataset == "collectortelemetry.otel"
| STATS failed_metric_points_rate = SUM(RATE(metrics.otelcol_exporter_send_failed_metric_points)) BY service.name, service.instance.id
| WHERE failed_metric_points_rate > 0
| SORT failed_metric_points_rate DESC

// Alert when the OpenTelemetry Collector reports non-zero rate of failed span exports.
//
// metrics.otelcol_exporter_send_failed_spans is a cumulative counter; RATE() yields per-bucket
// increases. TS is used for time-series metrics (counter resets handled by the TS pipeline).
//
// Scope: metrics-collectortelemetry* and collectortelemetry.otel dataset to avoid mixing with
// unrelated metrics-* streams.
//
// Grouping: service.name and service.instance.id help identify which collector instance fails.
// Add exporter dimension in your mapping if available (e.g. attributes.exporter).
//
// Tuning: raise the threshold (e.g. failed_rate > N) or require multiple consecutive runs via
// alert delay to reduce noise from brief blips.
//
TS metrics-collectortelemetry*
| WHERE data_stream.dataset == "collectortelemetry.otel"
| STATS failed_spans_rate = SUM(RATE(metrics.otelcol_exporter_send_failed_spans)) BY service.name, service.instance.id
| WHERE failed_spans_rate > 0
| SORT failed_spans_rate DESC

postgresql_otel-connection-utilization-h.esql:
FROM metrics-postgresqlreceiver.otel-*
// Include both server-level (connection.max) and database-level (backends) metrics
| WHERE postgresql.backends IS NOT NULL OR postgresql.connection.max IS NOT NULL
// Aggregate total backends and max connections per instance
| STATS total_backends = SUM(postgresql.backends), conn_max = MAX(postgresql.connection.max) BY service.instance.id
// Skip instances where we could not compute utilization
| WHERE conn_max > 0 AND total_backends IS NOT NULL
// Utilization as percentage; adjust 80.0 threshold for your environment
| EVAL utilization_pct = ROUND(total_backends / conn_max * 100.0, 2)
| WHERE utilization_pct > 80.0

postgresql_otel-high-rollback-rate.esql:
FROM metrics-postgresqlreceiver.otel-*
// Commits and rollbacks are monotonic counters per database
| WHERE postgresql.commits IS NOT NULL OR postgresql.rollbacks IS NOT NULL
| EVAL commits_val = TO_DOUBLE(postgresql.commits), rollbacks_val = TO_DOUBLE(postgresql.rollbacks)
| STATS total_commits = SUM(commits_val), total_rollbacks = SUM(rollbacks_val) BY service.instance.id, postgresql.database.name
// Minimum transaction volume to avoid noisy low-traffic databases
| WHERE total_commits > 10
// Rollback rate > 1% indicates application errors or contention; adjust threshold as needed
| EVAL rollback_rate_pct = CASE(total_commits > 0, ROUND(total_rollbacks / (total_commits + total_rollbacks) * 100.0, 2), 0.0)
| WHERE rollback_rate_pct > 1.0

redis_otel-high-eviction-rate.esql:
TS metrics-redisreceiver.otel-*
| WHERE redis.keys.evicted IS NOT NULL
// Counter: use INCREASE to get evictions over the time window
| STATS evicted = SUM(INCREASE(redis.keys.evicted))
  BY server.address, server.port
// Alert when evictions exceed threshold (adjust based on workload)
// Sudden spikes indicate memory pressure; sustained evictions may be normal for cache workloads
| WHERE evicted > 100
| SORT evicted DESC

redis_otel-replicas-disconnected.esql:
FROM metrics-redisreceiver.otel-*
| WHERE data_stream.dataset == "redisreceiver.otel"
  AND redis.slaves.connected IS NOT NULL
// Filter to primaries: role is primary when attributes.role exists, or check replication metrics
// redis.slaves.connected is only relevant on primaries (replicas report 0)
| STATS connected_replicas = MAX(redis.slaves.connected)
  BY server.address, server.port
// Alert when a primary expects replicas but has none (adjust if standalone is acceptable)
// Use 0 to alert on any instance with zero replicas; for HA setups this indicates risk
| WHERE connected_replicas == 0
| SORT server.address ASC

redisenterprise_otel-certificate-expirin.esql:
FROM metrics-redisenterprise.otel-default
| WHERE node_cert_expiration_seconds IS NOT NULL
| STATS min_expiry_s = MIN(node_cert_expiration_seconds) BY node, path, cluster
| EVAL days_until_expiry = ROUND(min_expiry_s / 86400, 1)
// Alert when any certificate expires within 30 days
// Expired certificates break intra-cluster communication and client TLS
// Adjust threshold: 30 days for early warning, 7 days is critical
// The 'path' dimension identifies which certificate file is expiring
| WHERE days_until_expiry < 30
| SORT days_until_expiry ASC

redisenterprise_otel-database-down.esql:
FROM metrics-redisenterprise.otel-default
| WHERE bdb_up IS NOT NULL
| STATS min_up = MIN(bdb_up) BY bdb, cluster
// Alert when any database reports as down (bdb_up < 1)
// This is a critical alert — a down database means clients cannot read or write
| WHERE min_up < 1

redisenterprise_otel-database-high-laten.esql:
FROM metrics-redisenterprise.otel-default
| WHERE bdb_avg_latency IS NOT NULL
| STATS avg_latency_s = AVG(bdb_avg_latency) BY bdb, cluster
| EVAL avg_latency_ms = ROUND(avg_latency_s * 1000, 2)
// Threshold: 5ms average latency — adjust based on your SLA
// Redis should deliver sub-millisecond responses; sustained >5ms warrants investigation
// Common causes: memory pressure, fork operations (AOF/RDB), hot shards
| WHERE avg_latency_ms > 5
| SORT avg_latency_ms DESC

redisenterprise_otel-database-unexpected.esql:
FROM metrics-redisenterprise.otel-default
| WHERE bdb_evicted_objects IS NOT NULL
| STATS max_evictions = MAX(bdb_evicted_objects) BY bdb, cluster
// Alert when evictions are detected (peak eviction rate > 0)
// For non-caching workloads, evictions indicate memory pressure and data loss risk
// For caching workloads with eviction policies, this is expected — disable this rule
// or raise the threshold to filter out normal eviction activity
| WHERE max_evictions > 0
| SORT max_evictions DESC

redisenterprise_otel-listener-auth-error.esql:
FROM metrics-redisenterprise.otel-default
| WHERE listener_auth_errors IS NOT NULL
| STATS max_auth_errors = MAX(listener_auth_errors) BY bdb, endpoint, node, cluster
// Alert when authentication failures are detected at any listener endpoint
// Possible causes: credential rotation issues, misconfigured clients,
// or unauthorized access attempts
// Adjust threshold if your environment has expected auth retries
| WHERE max_auth_errors > 0
| SORT max_auth_errors DESC

redisenterprise_otel-node-down.esql:
FROM metrics-redisenterprise.otel-default
| WHERE node_up IS NOT NULL
| STATS min_up = MIN(node_up) BY node, cluster
// Alert when any node reports as down (node_up < 1)
// A down node triggers automatic failover of its shards to replicas on other nodes
// Investigate host health, network connectivity, and management service status
| WHERE min_up < 1

redisenterprise_otel-node-low-memory.esql:
FROM metrics-redisenterprise.otel-default
| WHERE node_free_memory IS NOT NULL
| STATS avg_free = AVG(node_free_memory) BY node, cluster
| EVAL free_gb = ROUND(avg_free / 1073741824, 2)
// Alert when free memory drops below 1 GB
// Low node memory can cause OOM kills, swap thrashing, and fork failures
// Adjust threshold based on your node's total RAM and provisioning model
// Nodes with overbooking enabled may legitimately run with lower free memory
| WHERE free_gb < 1
| SORT free_gb ASC

redisenterprise_otel-shard-down.esql:
FROM metrics-redisenterprise.otel-default
| WHERE redis_up IS NOT NULL
| STATS min_up = MIN(redis_up) BY redis, bdb, node, role, cluster
// Alert when any shard reports as down (redis_up < 1)
// A primary shard going down triggers automatic failover to its replica
// A replica going down reduces redundancy — the database continues but is less resilient
| WHERE min_up < 1

redisenterprise_otel-shard-high-memory-f.esql:
FROM metrics-redisenterprise.otel-default
| WHERE redis_mem_fragmentation_ratio IS NOT NULL
    AND redis_used_memory IS NOT NULL
| STATS
    avg_frag = AVG(redis_mem_fragmentation_ratio),
    avg_used = AVG(redis_used_memory)
  BY redis, bdb, node, cluster
// Only evaluate shards with meaningful memory usage (>10 MB)
// Small shards naturally exhibit high fragmentation ratios
| WHERE avg_used > 10485760
// Alert when fragmentation ratio exceeds 1.5
// ratio = RSS / used_memory; values >> 1.0 indicate wasted memory
// Consider enabling active defragmentation or scheduling a restart
    AND avg_frag > 1.5
| SORT avg_frag DESC

supabase_otel-auth-api-server-errors.esql:
TS metrics-supabase.metrics.otel-*
// http_status_codes_total is a counter, one series per status code and route.
// Per-aggregation WHERE splits server errors from total requests in a single pass, so both
// sides of the ratio come from the same buckets. 4xx is carried as context only: bad
// passwords and expired tokens are routine auth traffic, not service failures.
| STATS
    `Server Errors` = SUM(INCREASE(http_status_codes_total)) WHERE attributes.code LIKE "5*",
    `Client Errors` = SUM(INCREASE(http_status_codes_total)) WHERE attributes.code LIKE "4*",
    `Requests` = SUM(INCREASE(http_status_codes_total))
  BY resource.attributes.supabase_project_ref
// Volume floor: a ratio over a handful of requests is noise, not signal.
| WHERE `Requests` >= 20
// The 5xx series does not exist until a 5xx occurs, so substitute zero for null.
| EVAL `Server Error %` = ROUND(CASE(`Server Errors` IS NULL, 0.0, `Server Errors`) / `Requests` * 100, 2)
// 5% of requests failing. Lower on high-traffic projects.
| WHERE `Server Error %` >= 5
| SORT `Server Error %` DESC

supabase_otel-auth-service-down.esql:
TS metrics-supabase.metrics.otel-*
// gotrue_running is a gauge: 1 = the Auth service is alive, 0 = it is not.
// MIN() across series so one unhealthy instance is not masked by a healthy one.
| STATS `Auth Running` = MIN(LAST_OVER_TIME(gotrue_running))
    BY resource.attributes.supabase_project_ref
| WHERE `Auth Running` == 0

supabase_otel-disk-io-saturation.esql:
TS metrics-supabase.metrics.otel-*
// node_disk_io_time_seconds_total is a counter of device busy time, so its per-second rate
// approximates utilisation (1.0 = busy for the whole window). Same metric and aggregation
// as the "Disk IO Time vs Disk Discard Time" dashboard panel.
| STATS
    `IO Time Rate` = SUM(RATE(node_disk_io_time_seconds_total)),
    `Weighted IO Time Rate` = SUM(RATE(node_disk_io_time_weighted_seconds_total))
  BY resource.attributes.supabase_project_ref, attributes.device
// Per-device rates can round marginally outside [0, 1], so clamp before presenting a %.
| EVAL `Disk IO Utilisation %` = ROUND(CLAMP(`IO Time Rate`, 0.0, 1.0) * 100, 1)
// Weighted time divided by busy time approximates average queue depth; above 1 means
// requests are queueing behind the device rather than merely keeping it busy.
| EVAL `Avg Queue Depth` = ROUND(`Weighted IO Time Rate` / CLAMP(`IO Time Rate`, 0.001, 1.0), 2)
// Lower on burstable compute tiers, where sustained high IO silently burns a credit balance.
| WHERE `Disk IO Utilisation %` >= 90
// One row per device, so the alert instance key includes it.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.device)
| SORT `Disk IO Utilisation %` DESC

supabase_otel-filesystem-nearly-full.esql:
TS metrics-supabase.metrics.otel-*
// Uncomment to ignore ephemeral mounts if your collector reports them.
// | WHERE attributes.fstype NOT IN ("tmpfs", "devtmpfs", "overlay", "squashfs")
// avail_bytes (not free_bytes) is the space actually usable by PostgreSQL, since it
// excludes root-reserved blocks. MIN()/MAX() take the worst-case headroom against the
// largest reported capacity for the mountpoint.
| STATS
    `Available Bytes` = MIN(LAST_OVER_TIME(node_filesystem_avail_bytes)),
    `Size Bytes` = MAX(LAST_OVER_TIME(node_filesystem_size_bytes))
  BY resource.attributes.supabase_project_ref, attributes.mountpoint, attributes.device
| WHERE `Size Bytes` > 0
| EVAL `Used %` = ROUND((1 - `Available Bytes` / `Size Bytes`) * 100, 1)
| EVAL `Available GB` = ROUND(`Available Bytes` / POW(1024, 3), 2)
// Tighten to 80 on small volumes, where 15% headroom is only a few hundred megabytes.
| WHERE `Used %` >= 85
// One row per mounted filesystem, so the alert instance key includes it.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.mountpoint, " / ", attributes.device)
| SORT `Used %` DESC

supabase_otel-filesystem-read-only.esql:
TS metrics-supabase.metrics.otel-*
// node_filesystem_readonly is a gauge: 1 = the kernel remounted the filesystem read-only.
// Same metric and aggregation as the "Filesystem Read-Only Status" dashboard panel.
| STATS
    `Read Only` = MAX(LAST_OVER_TIME(node_filesystem_readonly)),
    `Device Error` = MAX(LAST_OVER_TIME(node_filesystem_device_error))
  BY resource.attributes.supabase_project_ref, attributes.mountpoint, attributes.device
| WHERE `Read Only` == 1
// One row per mounted filesystem, so the alert instance key includes it.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.mountpoint, " / ", attributes.device)

supabase_otel-host-cpu-saturation.esql:
TS metrics-supabase.metrics.otel-*
// Utilisation is 1 - the idle rate. AVG(RATE()) averages the per-core rates, matching the
// "CPU Utilisation %" dashboard panel including its clamping CASE.
| STATS `Idle Rate` = AVG(RATE(node_cpu_seconds_total))
    BY resource.attributes.supabase_project_ref, attributes.mode
| WHERE attributes.mode == "idle"
// Per-core rates can land marginally outside [0, 1], so bound the derived percentage.
| EVAL `CPU Utilisation %` = CASE(
    `Idle Rate` >= 1, 0.0,
    `Idle Rate` <= 0, 100.0,
    ROUND((1 - `Idle Rate`) * 100, 1)
  )
// Sustained 90% on the small core counts of lower compute tiers means queries queue for CPU.
| WHERE `CPU Utilisation %` >= 90
| KEEP resource.attributes.supabase_project_ref, `CPU Utilisation %`

supabase_otel-host-memory-pressure.esql:
TS metrics-supabase.metrics.otel-*
// MemAvailable, never MemFree: PostgreSQL relies on the page cache, so free memory is
// expected to sit near zero while available memory is healthy. MIN() on the available
// side and MAX() on the capacity side give the worst-case headroom in the window.
| STATS
    `Available Bytes` = MIN(LAST_OVER_TIME(node_memory_MemAvailable_bytes)),
    `Total Bytes` = MAX(LAST_OVER_TIME(node_memory_MemTotal_bytes)),
    `Swap Total Bytes` = MAX(LAST_OVER_TIME(node_memory_SwapTotal_bytes)),
    `Swap Free Bytes` = MIN(LAST_OVER_TIME(node_memory_SwapFree_bytes)),
    `Dirty Bytes` = MAX(MAX_OVER_TIME(node_memory_Dirty_bytes))
  BY resource.attributes.supabase_project_ref
| WHERE `Total Bytes` > 0
| EVAL `Available Memory %` = ROUND(`Available Bytes` / `Total Bytes` * 100, 1)
// Swap usage is diagnostic context; null when the node has no swap configured.
| EVAL `Swap Used %` = CASE(
    `Swap Total Bytes` > 0, ROUND((1 - `Swap Free Bytes` / `Swap Total Bytes`) * 100, 1)
  )
// Below 10% available the buffer cache is being squeezed and an OOM kill is the next step.
// Raise to 15 on memory-tight compute tiers for earlier warning.
| WHERE `Available Memory %` < 10

supabase_otel-host-oom-kill.esql:
TS metrics-supabase.metrics.otel-*
// node_vmstat_oom_kill is a monotonic kernel counter published as a gauge, so DELTA()
// gives the number of new kills inside the window.
| STATS
    `OOM Kills` = SUM(DELTA(node_vmstat_oom_kill)),
    `Peak Kill Count` = MAX(MAX_OVER_TIME(node_vmstat_oom_kill)),
    `Available Memory Bytes` = MIN(MIN_OVER_TIME(node_memory_MemAvailable_bytes))
  BY resource.attributes.supabase_project_ref
// A node reboot zeroes the counter, making DELTA negative; fall back to the peak so a kill
// that preceded the reboot is not missed.
| EVAL `Counter Reset` = `OOM Kills` < 0
// A single OOM kill means the kernel terminated a process; never expected in normal operation.
| WHERE `OOM Kills` > 0 OR (`Counter Reset` AND `Peak Kill Count` > 0)

supabase_otel-long-running-transaction.esql:
TS metrics-supabase.metrics.otel-*
// Gauge, in seconds: the age of the longest running transaction. MAX_OVER_TIME() catches
// the peak within the window rather than whatever happened to be open at the last scrape.
| STATS
    `Longest Transaction (s)` = MAX(MAX_OVER_TIME(pg_stat_activity_xact_runtime)),
    `WAL Size (MB)` = MAX(LAST_OVER_TIME(pg_wal_size_mb))
  BY resource.attributes.supabase_project_ref
// 900s = 15 minutes. Lower to 300 for OLTP-only projects; raise if you run batch jobs.
| WHERE `Longest Transaction (s)` > 900
| SORT `Longest Transaction (s)` DESC

supabase_otel-metrics-collection-failing.esql:
TS metrics-supabase.metrics.otel-*
// Monitoring-health rule. All four are gauges: up / collector_success report 1 when healthy,
// last_scrape_error reports non-zero when the exporter failed. MIN() across series so one
// failing scrape target is not masked by a healthy one.
| STATS
    `Scrape Up` = MIN(LAST_OVER_TIME(up)),
    `PG Collector OK` = MIN(LAST_OVER_TIME(pg_scrape_collector_success)),
    `Node Collector OK` = MIN(LAST_OVER_TIME(node_scrape_collector_success)),
    `PG Scrape Error` = MAX(LAST_OVER_TIME(pg_exporter_last_scrape_error))
  BY resource.attributes.supabase_project_ref
// Absent gauges fall back to healthy defaults, since metric families come and go with
// project configuration.
| WHERE CASE(`Scrape Up` IS NULL, 1.0, `Scrape Up`) == 0
    OR CASE(`PG Collector OK` IS NULL, 1.0, `PG Collector OK`) == 0
    OR CASE(`Node Collector OK` IS NULL, 1.0, `Node Collector OK`) == 0
    OR CASE(`PG Scrape Error` IS NULL, 0.0, `PG Scrape Error`) > 0

supabase_otel-pgbouncer-client-queueing.esql:
TS metrics-supabase.metrics.otel-*
// pgbouncer_pools_client_maxwait_seconds is a gauge: the longest a client has currently
// been waiting for a server connection in this pool. AVG(AVG_OVER_TIME()) matches the
// dashboard panel; the peak and the waiting-client count are carried as context.
| STATS
    `Avg Client Wait (s)` = AVG(AVG_OVER_TIME(pgbouncer_pools_client_maxwait_seconds)),
    `Peak Client Wait (s)` = MAX(MAX_OVER_TIME(pgbouncer_pools_client_maxwait_seconds)),
    `Clients Waiting` = MAX(MAX_OVER_TIME(pgbouncer_pools_client_waiting_connections))
  BY resource.attributes.supabase_project_ref, attributes.database, attributes.user
// One second of average wait across the window means clients are blocked on the pool,
// not on the database. Lower to 0.5 for latency-sensitive workloads.
| WHERE `Avg Client Wait (s)` > 1
// One row per pool, so the alert instance key includes database and user.
| EVAL alert_instance = CONCAT(resource.attributes.supabase_project_ref, " / ", attributes.database, " / ", attributes.user)
| SORT `Avg Client Wait (s)` DESC

supabase_otel-pgbouncer-down.esql:
TS metrics-supabase.metrics.otel-*
// pgbouncer_up is a gauge: 1 = the pooler answered its admin console, 0 = it did not.
// MIN() across series so one unhealthy scrape target is not masked by a healthy one.
| STATS `PgBouncer Up` = MIN(LAST_OVER_TIME(pgbouncer_up))
    BY resource.attributes.supabase_project_ref
// Projects on the shared Supavisor pooler emit no pgbouncer_* series at all, so this
// query returns no rows for them rather than a false breach.
| WHERE `PgBouncer Up` == 0

supabase_otel-postgres-connection-satura.esql:
TS metrics-supabase.metrics.otel-*
// pg_stat_database_num_backends is the count PostgreSQL enforces against max_connections, so
// it is the numerator. The pooler-reported counts run lower because they see only their own
// clients; they are carried for attribution.
| STATS
    `Backends` = SUM(LAST_OVER_TIME(pg_stat_database_num_backends)),
    `Max Connections` = MAX(LAST_OVER_TIME(max_connections_connection_count)),
    `Pooled Connections` = SUM(LAST_OVER_TIME(connection_stats_connection_count)),
    `Direct Connections` = MAX(LAST_OVER_TIME(direct_connection_stats_connection_count))
  BY resource.attributes.supabase_project_ref
// Guard against a missing or zero ceiling producing a divide-by-zero percentage.
| WHERE `Max Connections` > 0
| EVAL `Connection Utilisation %` = ROUND(`Backends` / `Max Connections` * 100, 1)
// 90% leaves almost no headroom before new clients are refused. Supabase guidance is to
// keep the poolers under ~40% of max_connections when the REST API is busy, so lower this
// to 70-80% if you want earlier warning.
| WHERE `Connection Utilisation %` >= 90
| SORT `Connection Utilisation %` DESC

supabase_otel-postgres-deadlocks.esql:
TS metrics-supabase.metrics.otel-*
// Counter, cumulative since the last pg_stat_reset(); INCREASE() gives how many deadlocks
// actually occurred inside the window and is reset-safe.
| STATS
    `Deadlocks` = SUM(INCREASE(pg_stat_database_deadlocks_total)),
    `Rollbacks` = SUM(INCREASE(pg_stat_database_xact_rollback_total))
  BY resource.attributes.supabase_project_ref
// Deadlocks are application bugs, so any occurrence is worth surfacing. Raise to a small
// positive number only if your workload has a known, tolerated baseline.
| WHERE `Deadlocks` > 0
| SORT `Deadlocks` DESC

supabase_otel-postgres-down.esql:
TS metrics-supabase.metrics.otel-*
// pg_up is a gauge: 1 = the exporter reached PostgreSQL, 0 = it could not.
// MIN() across series so a single unhealthy scrape target is not masked by a healthy one.
// Swap LAST_OVER_TIME for MIN_OVER_TIME to also catch transient dips inside the window.
| STATS `Postgres Up` = MIN(LAST_OVER_TIME(pg_up))
    BY resource.attributes.supabase_project_ref
// If pg_up is absent entirely the STATS produces no row, so a project that does not
// expose the metric never triggers a false alert.
| WHERE `Postgres Up` == 0

supabase_otel-postgres-restarted.esql:
TS metrics-supabase.metrics.otel-*
// postgresql_restarts_total is a counter. INCREASE() is reset-safe, so a database that
// bounced (and therefore reset its own counters) is still counted correctly.
| STATS `Restarts` = SUM(INCREASE(postgresql_restarts_total))
    BY resource.attributes.supabase_project_ref
// Any restart is worth investigating. Raise above 0 only if rolling maintenance is expected.
| WHERE `Restarts` > 0

supabase_otel-postgrest-pool-timeouts.esql:
TS metrics-supabase.metrics.otel-*
// pgrst_db_pool_timeouts_total is a counter; INCREASE() gives how many timeouts actually
// happened inside the window (the dashboard charts the same metric as a per-second rate).
// pool_waiting and pool_available are gauges, carried here as diagnostic context.
| STATS
    `Pool Timeouts` = SUM(INCREASE(pgrst_db_pool_timeouts_total)),
    `Pool Waiting` = MAX(MAX_OVER_TIME(pgrst_db_pool_waiting)),
    `Pool Available` = MIN(MIN_OVER_TIME(pgrst_db_pool_available))
  BY resource.attributes.supabase_project_ref
// Any timeout is a failed API request. Raise if your clients retry transparently.
| WHERE `Pool Timeouts` > 0
| SORT `Pool Timeouts` DESC

supabase_otel-replication-lag.esql:
TS metrics-supabase.metrics.otel-*
// Replication series only exist when a replica or slot is attached; the physical lag gauge
// matches the "Physical Replication Lag" dashboard panel aggregation.
// Both compared gauges use LAST_OVER_TIME so they describe the same instant; peak is context.
| STATS
    `Physical Lag (s)` = MAX(LAST_OVER_TIME(physical_replication_lag_physical_replication_lag_seconds)),
    `Replay Lag (s)` = MAX(LAST_OVER_TIME(pg_stat_replication_replay_lag)),
    `Peak Replay Lag (s)` = MAX(MAX_OVER_TIME(pg_stat_replication_replay_lag)),
    `WAL Replay Paused` = MAX(LAST_OVER_TIME(physical_replication_lag_is_wal_replay_paused)),
    `Connected To Primary` = MIN(LAST_OVER_TIME(physical_replication_lag_is_connected_to_primary))
  BY resource.attributes.supabase_project_ref
// Both gauges use -1 to mean "not applicable" (no replica attached), so negatives and absent
// series collapse to 0 rather than being read as measurements.
| EVAL
    `Physical Lag (s)` = CASE(`Physical Lag (s)` > 0, `Physical Lag (s)`, 0.0),
    `Replay Lag (s)` = CASE(`Replay Lag (s)` > 0, `Replay Lag (s)`, 0.0),
    `Peak Replay Lag (s)` = CASE(`Peak Replay Lag (s)` > 0, `Peak Replay Lag (s)`, 0.0)
| EVAL `Lag (s)` = CASE(`Physical Lag (s)` >= `Replay Lag (s)`, `Physical Lag (s)`, `Replay Lag (s)`)
// 300s of lag means a read replica is serving materially stale data. Tighten to 60 where
// replica reads are expected to be near-real-time.
| WHERE `Lag (s)` > 300
| SORT `Lag (s)` DESC

supabase_otel-replication-slot-wal-reten.esql:
TS metrics-supabase.metrics.otel-*
// Gauges. WAL size uses the same aggregation as the "WAL Size" dashboard panel.
// Slot series only exist when a replication slot exists, so a project without one
// returns no rows rather than a false breach.
| STATS
    `Slot Max Lag Bytes` = MAX(LAST_OVER_TIME(replication_slots_max_lag_bytes)),
    `WAL Size (MB)` = MAX(LAST_OVER_TIME(pg_wal_size_mb))
  BY resource.attributes.supabase_project_ref
| EVAL `Slot Max Lag GB` = ROUND(`Slot Max Lag Bytes` / POW(1024, 3), 2)
// 10 GB of retained WAL. Size this against the free space on your data mountpoint —
// on small compute tiers a much lower value is already dangerous.
| WHERE `Slot Max Lag GB` > 10
| SORT `Slot Max Lag GB` DESC

temporal_otel-action-rate-limit.esql:
TS metrics-temporal.cloud_metrics.otel-*
// total_action_count is a rate (actions/s); action_limit is the provisioned cap (actions/s)
// action_limit only counts is_background=false actions (Temporal Cloud OpenMetrics)
// MAX ensures the limit value is the current provisioned limit
| STATS avg_actions = SUM(AVG_OVER_TIME(metrics.temporal_cloud_v1_total_action_count)) WHERE attributes.is_background == "false",
        action_limit = MAX(AVG_OVER_TIME(metrics.temporal_cloud_v1_action_limit))
    BY attributes.temporal_namespace
// Exclude namespaces with no limit data
| WHERE action_limit > 0
// Compute utilisation percentage
| EVAL utilization_pct = ROUND(avg_actions / action_limit * 100.0, 2)
// Alert at 80% to provide headroom before throttling begins
| WHERE utilization_pct > 80
| SORT utilization_pct DESC
| LIMIT 10

temporal_otel-activity-task-timeout.esql:
TS metrics-temporal.cloud_metrics.otel-*
// activity_task_timeout_count counts per-attempt timeouts by timeout_type
// These may be retried; persistent rates indicate systemic issues
| STATS timeout_rate = SUM(AVG_OVER_TIME(metrics.temporal_cloud_v1_activity_task_timeout_count))
    BY attributes.temporal_namespace, attributes.temporal_task_queue, attributes.timeout_type
// Alert threshold: 0.05/s (~3 per minute); tune for your workload
| WHERE timeout_rate > 0.05
| SORT timeout_rate DESC
| LIMIT 20

traefik_otel-file-descriptor-pressure.esql:
FROM metrics-traefik.otel-*
// Limit to process FD metrics
| WHERE process_open_fds IS NOT NULL AND process_max_fds IS NOT NULL
// Take latest values (gauges)
| STATS open_fds = MAX(process_open_fds), max_fds = MAX(process_max_fds)
// Compute utilisation; alert when > 80% (tune as needed)
| EVAL fd_pct = ROUND(open_fds / max_fds * 100.0, 2)
| WHERE fd_pct > 80.0

traefik_otel-high-5xx-rate-by-service.esql:
FROM metrics-traefik.otel-*
// Limit to service-level request counters (counter requires TS + INCREASE)
| WHERE traefik_service_requests_total IS NOT NULL
// Aggregate total and 5xx requests per service over the time window
| STATS
    total = SUM(traefik_service_requests_total),
    errors_5xx = SUM(traefik_service_requests_total) WHERE attributes.code LIKE "5*"
  BY attributes.service
// Minimum sample size to avoid noisy low-traffic services; adjust based on expected volume
| WHERE total > 100
// Calculate error rate as percentage
| EVAL error_rate_pct = ROUND(errors_5xx / total * 100.0, 2)
// Alert threshold: tune for sensitivity (e.g. 5.0 = 5%)
| WHERE error_rate_pct > 5.0
| SORT error_rate_pct DESC
| LIMIT 10

traefik_otel-high-goroutine-count.esql:
FROM metrics-traefik.otel-*
// Limit to Go runtime goroutine gauge
| WHERE go_goroutines IS NOT NULL
// Take max goroutine count in window (gauge)
| STATS goroutines = MAX(go_goroutines)
// Alert when goroutines exceed threshold; tune for typical baseline (e.g. 500-2000)
| WHERE goroutines > 2000

traefik_otel-high-memory-usage.esql:
FROM metrics-traefik.otel-*
// Limit to process resident memory gauge (RSS)
| WHERE process_resident_memory_bytes IS NOT NULL
// Take max RSS in window
| STATS memory_bytes = MAX(process_resident_memory_bytes)
// Convert to GB; alert when > 2GB (tune based on expected workload)
| EVAL memory_gb = ROUND(memory_bytes / 1073741824.0, 2)
| WHERE memory_gb > 2.0

traefik_otel-high-open-connections.esql:
FROM metrics-traefik.otel-*
// Limit to open connections gauge (per entrypoint, protocol)
| WHERE traefik_open_connections IS NOT NULL
// Take latest value per entrypoint/protocol (gauge - last value in window)
| STATS conns = MAX(traefik_open_connections) BY attributes.entrypoint, attributes.protocol
// Sum across entrypoints for total, or alert per entrypoint
| STATS total_conns = SUM(conns)
// Alert when connections exceed threshold; tune based on expected capacity
| WHERE total_conns > 1000

traefik_otel-stale-config-reload.esql:
FROM metrics-traefik.otel-*
// Limit to last successful reload timestamp (gauge, Unix epoch)
| WHERE traefik_config_last_reload_success IS NOT NULL
// Take latest value
| STATS last_success_epoch = MAX(traefik_config_last_reload_success)
// If last success was > 24h ago, config may be stuck or reloads failing
// Adjust 24 to match expected reload frequency
| EVAL last_success_dt = TO_DATETIME(last_success_epoch * 1000)
| EVAL hours_since_reload = DATE_DIFF("hours", last_success_dt, NOW())
| WHERE hours_since_reload > 24

traefik_otel-tls-cert-expiry-imminent.esql:
FROM metrics-traefik.otel-*
// Limit to TLS cert expiry timestamps (Unix epoch seconds)
| WHERE traefik_tls_certs_not_after IS NOT NULL
// Take latest expiry per cert (cn + serial)
| STATS expiry_epoch = MAX(traefik_tls_certs_not_after) BY attributes.cn, attributes.serial
// Convert epoch seconds to datetime; compute days until expiry
// Adjust 30-day threshold based on renewal lead time
| EVAL expiry_datetime = TO_DATETIME(expiry_epoch * 1000)
| EVAL days_until_expiry = DATE_DIFF("days", NOW(), expiry_datetime)
| WHERE days_until_expiry < 30 AND days_until_expiry >= 0
| SORT days_until_expiry ASC

vercel_otel-firewall-deny-spike.esql:
FROM logs-vercel.logs.otel-default
| WHERE deployment.environment.name == "production"
    AND vercel.log.source == "firewall"
// vercel.proxy is a flattened field; sub-fields aren't queryable via dotted notation, use FIELD_EXTRACT instead
| EVAL waf_action = FIELD_EXTRACT(vercel.proxy, "waf_action")
// "firewall" source includes log-only entries too; isolate actual blocks
| WHERE waf_action == "deny"
| STATS denies = COUNT(*)
// Alert threshold: tune based on your application's normal WAF deny baseline.
// Consider grouping by client.address instead of a flat total if you want per-attacker alerting.
| WHERE denies > 100

vercel_otel-high-5xx-error-rate-by-sourc.esql:
FROM logs-vercel.logs.otel-default
// Restrict to sources that produce genuine HTTP responses (lambda/edge); static/firewall/redirect/external are covered by other rules
// Exclude deployment.environment.name filter or add preview back in if you want to monitor non-production traffic
| WHERE deployment.environment.name == "production"
    AND vercel.log.source IN ("lambda", "edge")
    // -1 means the function crashed before returning any response; excluded here, tracked by the crash-rate rule instead
    AND http.response.status_code != -1
| STATS
    total = COUNT(*),
    errors = COUNT(*) WHERE http.response.status_code >= 500
  BY vercel.log.source
// Minimum sample size to avoid noisy alerts on low-traffic sources; raise this for high-traffic production apps
| WHERE total > 20
// TO_DOUBLE(...) avoids integer division truncation before the percentage multiplication
| EVAL error_rate_pct = ROUND(TO_DOUBLE(errors) / total * 100.0, 2)
// Alert threshold: the spec's healthy baseline is <1%; set slightly above that to reduce noise from brief blips.
// Tighten to 1.0 for stricter SLA-aligned alerting, or raise for noisier/lower-traffic deployments.
| WHERE error_rate_pct > 2.0
| SORT error_rate_pct DESC
| LIMIT 10

vsphere_otel-host-disk-latency-high.esql:
FROM metrics-vcenterreceiver.otel-*
// Host disk latency max (ms): healthy <15ms; unhealthy >30ms
// Uses max latency per object; use vcenter.host.disk.latency.avg if available for finer granularity
// Adjust threshold to suit storage tier
| WHERE vcenter.host.disk.latency.max IS NOT NULL AND vcenter.host.disk.latency.max > 15
| STATS latency_ms = MAX(vcenter.host.disk.latency.max) BY vcenter.datacenter.name, vcenter.cluster.name, vcenter.host.name, attributes.object
| SORT latency_ms DESC
| LIMIT 20

vsphere_otel-host-power-state-unhealthy.esql:
FROM metrics-vcenterreceiver.otel-*
// Datacenter host count by power_state: off or standby indicates problems
// May indicate hardware failure or unplanned maintenance
// Excludes "on" and "unknown"; adjust if unknown should be included
| WHERE vcenter.datacenter.host.count IS NOT NULL
  AND attributes.power_state IN ("off", "standby")
  AND vcenter.datacenter.host.count > 0
| STATS host_count = MAX(vcenter.datacenter.host.count) BY vcenter.datacenter.name, attributes.power_state
| SORT host_count DESC
| LIMIT 20

vsphere_otel-vm-disk-latency-high.esql:
FROM metrics-vcenterreceiver.otel-*
// VM disk latency max (ms): healthy <20ms; unhealthy >30ms
// Uses max latency per object; use vcenter.vm.disk.latency.avg if available for finer granularity
// Adjust threshold to suit workload
| WHERE vcenter.vm.disk.latency.max IS NOT NULL AND vcenter.vm.disk.latency.max > 20
| STATS latency_ms = MAX(vcenter.vm.disk.latency.max) BY vcenter.datacenter.name, vcenter.cluster.name, vcenter.host.name, vcenter.vm.name, attributes.object
| SORT latency_ms DESC
| LIMIT 20

zookeeper_otel-data-tree-size-excessive.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.data_tree.size IS NOT NULL
// Peak data tree size per node in the time window
| STATS max_data_size = MAX(metrics.zookeeper.data_tree.size) BY host.name
// Alert when the in-memory data tree exceeds 1 GB (1,073,741,824 bytes)
// Unbounded growth causes memory pressure, GC pauses, and latency spikes
// Adjust based on available heap memory
| WHERE max_data_size > 1073741824

zookeeper_otel-excessive-watch-count.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.watch.count IS NOT NULL
// Peak watch count per node in the time window
| STATS max_watches = MAX(metrics.zookeeper.watch.count) BY host.name
// Official docs recommend alerting above 10,000 watches
// High watch counts risk notification storms during topology changes
// Adjust based on your client workload and Kafka topology size
| WHERE max_watches > 10000

zookeeper_otel-excessive-znode-count.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.znode.count IS NOT NULL
// Peak znode count per node in the time window
| STATS max_znodes = MAX(metrics.zookeeper.znode.count) BY host.name
// Official ZooKeeper docs recommend alerting above 1,000,000 znodes
// Excessive znodes cause memory pressure and slow startup/recovery
// Adjust based on your expected data model size
| WHERE max_znodes > 1000000

zookeeper_otel-file-descriptor-utilizati.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.file_descriptor.open IS NOT NULL
  AND metrics.zookeeper.file_descriptor.limit IS NOT NULL
// Compute FD utilization as a percentage
| EVAL fd_pct = metrics.zookeeper.file_descriptor.open * 100.0
  / metrics.zookeeper.file_descriptor.limit
// Take the peak utilization per node in the time window
| STATS max_fd_pct = MAX(fd_pct) BY host.name
// 80% threshold — approaching the limit causes connection refusals
// Each client connection uses one FD plus FDs for data/transaction logs
// Adjust based on your configured FD limits
| WHERE max_fd_pct > 80

zookeeper_otel-high-average-latency.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.latency.max IS NOT NULL
// Average the peak-latency gauge readings per node across the time window
// latency.max reports the highest request latency since the last collection
| STATS avg_peak_latency = AVG(metrics.zookeeper.latency.max) BY host.name
// Threshold: sustained peak latency above 500 ms signals degradation
// Sustained high latency risks Kafka broker session timeouts
// Adjust based on your ensemble's baseline and SLA requirements
| WHERE avg_peak_latency > 500

zookeeper_otel-node-health-check-failed.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.ruok IS NOT NULL
// Aggregate per node; MIN captures any unhealthy reading in the window
| STATS min_ruok = MIN(metrics.zookeeper.ruok) BY host.name
// ruok = 0 means the node failed its health check and is not serving requests
// This is the most direct signal of ZooKeeper node availability
| WHERE min_ruok == 0

zookeeper_otel-outstanding-requests-satu.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.request.active IS NOT NULL
// Average outstanding requests per node over the time window
| STATS avg_outstanding = AVG(metrics.zookeeper.request.active) BY host.name
// A healthy ensemble should have near-zero outstanding requests
// Sustained values above this threshold indicate processing saturation
// Adjust based on your workload; lower values catch issues sooner
| WHERE avg_outstanding > 10

zookeeper_otel-pending-syncs-buildup.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.sync.pending IS NOT NULL
  AND resource.attributes.server.state == "leader"
// Average pending syncs on the leader over the time window
| STATS avg_pending = AVG(metrics.zookeeper.sync.pending) BY host.name
// A healthy leader should have zero pending syncs
// Sustained buildup means the ZAB protocol is struggling to replicate
// This is an early warning before followers become unsynced
// Adjust threshold based on ensemble size and write volume
| WHERE avg_pending > 10

zookeeper_otel-unsynced-followers.esql:
FROM metrics-generic.otel-default
| WHERE metrics.zookeeper.follower.count IS NOT NULL
  AND resource.attributes.server.state == "leader"
  AND attributes.state == "unsynced"
// Peak unsynced follower count reported by the leader
| STATS max_unsynced = MAX(metrics.zookeeper.follower.count) BY host.name
// Any unsynced followers risk data loss during failover
// and indicate replication lag or network issues between ensemble members
| WHERE max_unsynced > 0
